// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _minSum, uint256 _lockTime, uint256 _putAmount, uint256 _collectAmount, uint256 _timeJump) public {
        // Bound parameters to reasonable ranges
        _minSum = bound(_minSum, 0, 1e18);
        _lockTime = bound(_lockTime, 0, 365 days);
        _putAmount = bound(_putAmount, 1, 1e18);
        _collectAmount = bound(_collectAmount, 0, 1e18);
        _timeJump = bound(_timeJump, 0, 730 days);

        // Initialize and set MinSum
        c.SetMinSum(_minSum);
        c.Initialized();

        // Fund the contract with some ETH for potential collect
        vm.deal(address(c), 1e18);

        // Put some ETH for msg.sender
        vm.deal(address(this), _putAmount);
        c.Put{value: _putAmount}(_lockTime);

        // Record MinSum before Collect
        uint256 minSumBefore = c.MinSum();

        // Warp time to satisfy unlock condition
        vm.warp(block.timestamp + _lockTime + _timeJump);

        // Call Collect
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, _collectAmount));

        // After Collect, MinSum must equal its value before Collect if it didn't revert
        if (success) {
            assertTrue(c.MinSum() == minSumBefore, "MinSum changed after successful Collect");
        } else {
            // If it reverted, MinSum should still be unchanged
            assertTrue(c.MinSum() == minSumBefore, "MinSum changed after reverted Collect");
        }
    }
}

