        vm.assume(_lockTime < type(uint40).max);
        vm.assume(_putAmount < 1e30);
        vm.assume(_collectAmount < 1e30);
        vm.assume(_val < 1e30);

        // Step 1: Call SetMinSum, capture the value it should become (but bug may set to 0)
        c.SetMinSum(_val);
        uint256 expectedMinSum = _val; // Reference: MinSum = _val

        // Step 2: Initialize (prevent further SetMinSum calls)
        c.Initialized();

        // Step 3: Put some value (to allow later collect)
