        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", _am));

        // Get balance after Collect (only if call succeeded)
        if (success) {
            (uint afterBal, ) = c.Acc(caller);
            // In the reference, balance should increase by _am (caller's balance goes up by _am because the subtraction is replaced with addition in the buggy version; but in the reference it should decrease by _am, so the net change is +_am for buggy and -_am for reference)
